import{_ as a,o,c as t,a2 as n}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"본관과 항렬","description":"","frontmatter":{},"headers":[],"relativePath":"world/Hangnyeol-and-Bon-gwan.md","filePath":"world/Hangnyeol-and-Bon-gwan.md"}'),r={name:"world/Hangnyeol-and-Bon-gwan.md"};function l(i,e,d,s,h,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="본관과-항렬" tabindex="-1">본관과 항렬 <a class="header-anchor" href="#본관과-항렬" aria-label="Permalink to &quot;본관과 항렬&quot;">​</a></h1><p>유교 문화권에서 같은 성만으로는 한 집안이 아니다. 한국은 <strong>본관</strong>(본)으로 갈래를 나누고, 같은 갈래 안에서는 <strong>항렬자</strong>(돌림자)로 세대를 표시한다. 중국의 자배(字輩), 일본의 통자(通字)도 같은 논리다. 잔선 생성기는 성을 고른 뒤, 명문·족보를 지키는 집만 항렬을 이름 한 글자에 넣는다.</p><p>이 페이지는 생성 규칙이다. 실존 족보 항렬표를 베끼지 않는다. 시퀀스는 <a href="name-pools/clans-hangnyeol.json">clans-hangnyeol.json</a>의 창작 시드다.</p><h2 id="출처-열람-2026-09-11" tabindex="-1">출처 (열람 2026-09-11) <a class="header-anchor" href="#출처-열람-2026-09-11" aria-label="Permalink to &quot;출처 (열람 2026-09-11)&quot;">​</a></h2><ul><li>한국 본관: 같은 성이라도 시조·발상지가 다르면 다른 혈족으로 본다. (<a href="https://en.wikipedia.org/wiki/Bon-gwan" target="_blank" rel="noreferrer">Bon-gwan</a>)</li><li>한국 항렬: 이름 한 글자를 세대 공유 한자로 둔다. 돌림자라고도 한다. (<a href="https://ko.wikipedia.org/wiki/%ED%95%AD%EB%A0%AC" target="_blank" rel="noreferrer">항렬</a>)</li><li>세대자 일반: 중국·한국·베트남에서 형제·사촌이 이름 한 글자를 공유한다. (<a href="https://en.wikipedia.org/wiki/Generation_name" target="_blank" rel="noreferrer">Generation name</a>)</li><li>중국 자배: 족보에 미리 적어 둔 글자 순서. 항렬과 같다.</li><li>일본 통자: 무가·명문이 이름 한 글자를 대대로 물려 쓰는 경향. 잔선 공개면은 일본식 자를 쓰지 않는다. (<a href="/world/Core-Characters.html">작명 원칙</a>)</li></ul><p>현대 한국은 항렬을 안 쓰는 집이 많다. 붕괴 이후에도 기록청·수문 가문·상단 가문처럼 장부를 지키는 집만 높은 확률로 지킨다. 떠돌이·기숙 노동은 거의 안 쓴다.</p><h2 id="풀을-나누는-법" tabindex="-1">풀을 나누는 법 <a class="header-anchor" href="#풀을-나누는-법" aria-label="Permalink to &quot;풀을 나누는 법&quot;">​</a></h2><p>성, 남성 이름, 여성 이름은 <strong>서로 다른 파일</strong>이다.</p><table tabindex="0"><thead><tr><th>파일</th><th>내용</th></tr></thead><tbody><tr><td><a href="name-pools/surnames.json">surnames.json</a></td><td>한 글자 성</td></tr><tr><td><a href="name-pools/given-male.json">given-male.json</a></td><td>남성 이름 두 글자</td></tr><tr><td><a href="name-pools/given-female.json">given-female.json</a></td><td>여성 이름 두 글자</td></tr><tr><td><a href="name-pools/clans-hangnyeol.json">clans-hangnyeol.json</a></td><td>본관과 항렬 시퀀스</td></tr></tbody></table><p>성별을 가리지 않는 통용 칸은 후계 문서의 <code>given-open</code>으로 남긴다. 랜덤 로스터는 데이터셋 <code>sex</code>가 있으면 남·여 풀만 쓴다.</p><h2 id="생성-순서" tabindex="-1">생성 순서 <a class="header-anchor" href="#생성-순서" aria-label="Permalink to &quot;생성 순서&quot;">​</a></h2><ol><li>성 풀에서 성을 고른다.</li><li>그 성에 본관 시드가 있고, 집안이 항렬을 지키는 좌면이면 <code>keepRate</code>로 항렬을 켤지 정한다.</li><li>나이대로 세대 칸을 고른다. 대략 60+ / 40–59 / 25–39 / 24 이하 → 시퀀스 0–3.</li><li>성별 이름 풀에서 두 글자를 고른다.</li><li>항렬이 켜지면 이름 <strong>앞글자</strong>를 그 세대 항렬자로 덮어쓴다. (위치는 <code>position: first-syllable</code>)</li><li><code>성+이름</code>이 이미 생존·사망 기록에 있으면 4로 돌아간다. 8번 실패하면 생성을 거부한다.</li></ol><p>예: 성 김, 본관 김해, 세대 2, 이름 풀 <code>지훈</code> → <code>김석훈</code>. 같은 세대 형제는 <code>석</code>을 공유한다.</p><p>이주민 회랑 이름은 이 항렬을 강제하지 않는다. 한글 음차는 <a href="/world/Cast-Profile-Contract.html">인물 카드 계약</a>대로 옆에 둔다.</p><h2 id="넣지-말-것" tabindex="-1">넣지 말 것 <a class="header-anchor" href="#넣지-말-것" aria-label="Permalink to &quot;넣지 말 것&quot;">​</a></h2><ul><li>실존 김해김씨·전주이씨 족보 항렬표 복사</li><li>일본식 자(通字)를 공개 카피에 쓰기</li><li>모든 한국 인물에게 항렬 강제</li></ul>',16)])])}const f=a(r,[["render",l]]);export{g as __pageData,f as default};
